<?php
require 'page-guard.php'; require '../config/db_conn.php'; require '../includes/teacher-profile-schema.php'; require '../includes/student-placement-options.php'; require '../includes/section-catalog-schema.php'; ensureTeacherProfileColumns($conn); ensureSectionCatalogColumns($conn); seedDefaultTeacherSections($conn);
$id=(int)($_POST['id']??0); $passwordOnly=($_POST['password_only']??'')==='1'; $current=$_POST['current_password']??''; $pass=$_POST['teacher_pass']??''; $confirm=$_POST['teacher_confirm']??'';
$find=$conn->prepare('SELECT TEACHER_PASS FROM teachers WHERE TEACHER_ID=?'); $find->bind_param('i',$id); $find->execute(); $existing=$find->get_result()->fetch_assoc(); if(!$existing)exit('Teacher not found.');
if($passwordOnly){if(!password_verify($current,$existing['TEACHER_PASS'])||strlen($pass)<8||$pass!==$confirm)exit('Current password is incorrect or the new passwords do not match.');$hash=password_hash($pass,PASSWORD_DEFAULT);$stmt=$conn->prepare('UPDATE teachers SET TEACHER_PASS=? WHERE TEACHER_ID=?');$stmt->bind_param('si',$hash,$id);$stmt->execute();$_SESSION['toast']=['message'=>'Teacher password updated successfully.','type'=>'success'];header('Location: edit-teacher.php?id='.$id);exit;}
