if($firstName===''||$lastName===''||!isApprovedTeacherSection($conn,$grade,$strand,$section)||!$validAssignment)exit('Invalid teacher details, grade, section, or assignment.');
$stmt=$conn->prepare('UPDATE teachers SET TEACHER_NAME=?,FIRST_NAME=?,LAST_NAME=?,GRADE=?,STRAND=?,SECTION=?,SUBJECT=? WHERE TEACHER_ID=?');$stmt->bind_param('sssisssi',$name,$firstName,$lastName,$grade,$strand,$section,$subject,$id);$stmt->execute();$_SESSION['toast']=['message'=>'Teacher profile updated successfully.','type'=>'success'];header('Location: edit-teacher.php?id='.$id);exit;
